#
# StorageBackend interface. save() streams the input in chunks (never loads
# a whole file into memory) and returns (size_bytes, sha256_hex) computed in
# the same pass. Implementations receive keys generated by the caller
# (always UUID-based, never user-supplied) so they never need to sanitize
# a path themselves.

from abc import ABC, abstractmethod
from typing import BinaryIO


class StorageBackend(ABC):
    @abstractmethod
    def save(self, key: str, file: BinaryIO) -> tuple[int, str]: ...

    @abstractmethod
    def open(self, key: str) -> BinaryIO: ...

    @abstractmethod
    def delete(self, key: str) -> None: ...
